from IQEngine.interface import AbstractPlugin
from IQEngine.plugins.plugin_system_simulation.broker import SimulationBroker
from IQEngine.plugins.plugin_system_simulation.live import DefaultLiveBroker
from IQEngine.const import RunType
class PluginBroker(AbstractPlugin):
    def setup(self, engine):
        if (engine.config.strategy.run_type == RunType.TRADING):
            algo = DefaultLiveBroker(engine)
        elif (engine.config.strategy.run_type == RunType.BACKTEST):
            algo = SimulationBroker(engine)
        elif (engine.config.strategy.run_type == RunType.MIXING):
            algo = SimulationBroker(engine)
        else:
            return None
        engine.set_broker(algo)
    def cleanup(self, code, exception=None):
        return None
    def interface(self):
        return self
def load_plugin():
    return PluginBroker()
